     1	import type { Step1Output } from './field-config.model';
     2	import { ageOn, parseIsoDate } from './field-validators';
     3	
     4	/**
     5	 * Simulated price rule (ADR-0007, option A; spec 7.6). Pure: no Angular, no clock of its own, the
     6	 * same for every country. Factors are whole percentages so every step is integer arithmetic.
     7	 * US-03 imports `calculateFinalPrice` instead of copying it. The factors are illustrative, not
     8	 * actuarial. A band with `toYears: null` has no upper limit.
     9	 */
    10	export interface FactorBand {
    11	  fromYears: number;
    12	  toYears: number | null;
    13	  factorPercent: number;
    14	}
    15	
    16	/** Driver age in completed years on today's local date. */
    17	export const DRIVER_AGE_FACTORS: readonly FactorBand[] = [
    18	  { fromYears: 18, toYears: 25, factorPercent: 120 },
    19	  { fromYears: 26, toYears: 60, factorPercent: 100 },
    20	  { fromYears: 61, toYears: null, factorPercent: 110 },
    21	];
    22	
    23	/** Vehicle age: the year of today minus `vehicleYear`, never below 0. */
    24	export const VEHICLE_AGE_FACTORS: readonly FactorBand[] = [
    25	  { fromYears: 0, toYears: 5, factorPercent: 110 },
    26	  { fromYears: 6, toYears: 10, factorPercent: 100 },
    27	  { fromYears: 11, toYears: null, factorPercent: 90 },
    28	];
    29	
    30	/** Used when an input is missing or matches no band (always with a warning). */
    31	const NEUTRAL_PERCENT = 100;
    32	const PERCENT_SCALE = 10_000; // two factors, each a percentage
    33	
    34	function factorFor(bands: readonly FactorBand[], years: number): number | null {
    35	  const band = bands.find((b) => years >= b.fromYears && (b.toYears === null || years <= b.toYears));
    36	  return band ? band.factorPercent : null;
    37	}
    38	
    39	function driverFactor(birthDate: unknown, today: Date): number {
    40	  const birth = typeof birthDate === 'string' ? parseIsoDate(birthDate) : null;
    41	  if (!birth) {
    42	    console.warn('price rule: birthDate is missing or invalid, the neutral factor is used');
    43	    return NEUTRAL_PERCENT;
    44	  }
    45	  const factor = factorFor(DRIVER_AGE_FACTORS, ageOn(birth, today));
    46	  if (factor === null) {
    47	    console.warn('price rule: the driver age matches no band, the neutral factor is used');
    48	    return NEUTRAL_PERCENT;
    49	  }
    50	  return factor;
    51	}
    52	
    53	function vehicleFactor(vehicleYear: unknown, today: Date): number {
    54	  if (typeof vehicleYear !== 'number' || !Number.isInteger(vehicleYear)) {
    55	    console.warn('price rule: vehicleYear is missing or invalid, the neutral factor is used');
    56	    return NEUTRAL_PERCENT;
    57	  }
    58	  const factor = factorFor(VEHICLE_AGE_FACTORS, Math.max(0, today.getFullYear() - vehicleYear));
    59	  if (factor === null) {
    60	    console.warn('price rule: the vehicle age matches no band, the neutral factor is used');
    61	    return NEUTRAL_PERCENT;
    62	  }
    63	  return factor;
    64	}
    65	
    66	/**
    67	 * `roundHalfUp(basePrice x driverFactor x vehicleFactor)` in integers, at least 1. `today` is the
    68	 * injectable clock's date (US-01-Q-06). Warnings name the key, never a value.
    69	 */
    70	export function calculateFinalPrice(basePrice: number, step1: Step1Output, today: Date): number {
    71	  const driver = driverFactor(step1.values['birthDate'], today);
    72	  const vehicle = vehicleFactor(step1.values['vehicleYear'], today);
    73	  const scaled = basePrice * driver * vehicle;
    74	  return Math.max(1, Math.floor((scaled + PERCENT_SCALE / 2) / PERCENT_SCALE));
    75	}
