     1	const formatters = new Map<string, Intl.NumberFormat>();
     2	
     3	/**
     4	 * A price in the country's currency (US-02-AC-06): `Intl.NumberFormat` currency style with the
     5	 * country's `locale` and `currencyCode`, no fraction digits, grouping always on. Nothing here
     6	 * knows a country; an invalid locale or currency makes `Intl` throw a `RangeError`, which the
     7	 * caller turns into its error state.
     8	 */
     9	export function formatMoney(amount: number, locale: string, currencyCode: string): string {
    10	  const cacheKey = `${locale}|${currencyCode}`;
    11	  let formatter = formatters.get(cacheKey);
    12	  if (!formatter) {
    13	    // `useGrouping: 'always'` (ES2023) is missing from the ES2022 typings of this project; Spanish
    14	    // locales would otherwise leave four-digit amounts ungrouped.
    15	    const options = {
    16	      style: 'currency',
    17	      currency: currencyCode,
    18	      minimumFractionDigits: 0,
    19	      maximumFractionDigits: 0,
    20	      useGrouping: 'always',
    21	    } as unknown as Intl.NumberFormatOptions;
    22	    formatter = new Intl.NumberFormat(locale, options);
    23	    formatters.set(cacheKey, formatter);
    24	  }
    25	  return formatter.format(amount);
    26	}
