     1	import type { Plan } from './plan.model';
     2	
     3	const isRec = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
     4	const isNonBlank = (v: unknown): v is string => typeof v === 'string' && v.trim() !== '';
     5	
     6	const KEY_PATTERN = /^[a-z][a-z0-9-]*$/;
     7	const MAX_BASE_PRICE = 2_147_483_647;
     8	
     9	/** The non-blank labels of a component list; blank items are skipped with a warning. */
    10	function labelsOf(key: string, attribute: string, raw: unknown): string[] | null {
    11	  if (!Array.isArray(raw)) return null;
    12	  const labels: string[] = [];
    13	  let skipped = false;
    14	  for (const item of raw) {
    15	    if (isRec(item) && isNonBlank(item['label'])) labels.push(item['label']);
    16	    else skipped = true;
    17	  }
    18	  if (skipped) console.warn(`plans: "${key}" skipped a blank line in ${attribute}`);
    19	  return labels;
    20	}
    21	
    22	/** A plan, `'inactive'` when it is not offered, or the name of the first invalid attribute. */
    23	function parseItem(raw: unknown): Plan | 'inactive' | string {
    24	  if (!isRec(raw)) return 'item';
    25	  if (raw['isActive'] !== true) return 'inactive';
    26	  const key = raw['key'];
    27	  if (typeof key !== 'string' || !KEY_PATTERN.test(key)) return 'key';
    28	  if (!isNonBlank(raw['name'])) return 'name';
    29	  if (!isNonBlank(raw['shortDescription'])) return 'shortDescription';
    30	  const price = raw['basePrice'];
    31	  if (typeof price !== 'number' || !Number.isInteger(price) || price < 1 || price > MAX_BASE_PRICE) return 'basePrice';
    32	  const sortOrder = raw['sortOrder'];
    33	  if (typeof sortOrder !== 'number' || !Number.isInteger(sortOrder)) return 'sortOrder';
    34	  const coverages = labelsOf(key, 'coverages', raw['coverages']);
    35	  if (coverages === null || coverages.length === 0) return 'coverages';
    36	  const rawBenefits = raw['benefits'];
    37	  const benefits = rawBenefits === null || rawBenefits === undefined ? [] : labelsOf(key, 'benefits', rawBenefits);
    38	  if (benefits === null) return 'benefits';
    39	  return {
    40	    key,
    41	    name: raw['name'],
    42	    shortDescription: raw['shortDescription'],
    43	    basePrice: price,
    44	    sortOrder,
    45	    isRecommended: raw['isRecommended'] === true,
    46	    coverages,
    47	    benefits,
    48	  };
    49	}
    50	
    51	/**
    52	 * Boundary validation of the plans response (spec 7.2, US-02-Q-18). Returns the offered plans
    53	 * (`isActive` is `true`), sorted by `sortOrder` then `key`; the server sort is not trusted. A
    54	 * malformed plan is dropped with a warning that names its key and the attribute, never a value.
    55	 * For a repeated key the first in display order wins. Throws when the body is not a list at all
    56	 * (the page then shows its error state).
    57	 */
    58	export function parsePlans(body: unknown): Plan[] {
    59	  const data = isRec(body) ? body['data'] : null;
    60	  if (!Array.isArray(data)) throw new Error('plans: unexpected response shape');
    61	  const parsed: Plan[] = [];
    62	  for (const raw of data) {
    63	    const result = parseItem(raw);
    64	    if (result === 'inactive') continue;
    65	    if (typeof result === 'string') {
    66	      const key = isRec(raw) && typeof raw['key'] === 'string' ? raw['key'] : '(unreadable)';
    67	      console.warn(`plans: "${key}" dropped (invalid ${result})`);
    68	    } else {
    69	      parsed.push(result);
    70	    }
    71	  }
    72	  parsed.sort((a, b) => a.sortOrder - b.sortOrder || (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
    73	  const seen = new Set<string>();
    74	  const plans = parsed.filter((plan) => {
    75	    if (seen.has(plan.key)) {
    76	      console.warn(`plans: "${plan.key}" dropped (duplicated key)`);
    77	      return false;
    78	    }
    79	    seen.add(plan.key);
    80	    return true;
    81	  });
    82	  const flagged = plans.filter((p) => p.isRecommended);
    83	  if (flagged.length > 1) console.warn(`plans: ${flagged.length} plans are flagged as recommended, only "${flagged[0].key}" is highlighted`);
    84	  return plans;
    85	}
    86	
    87	/** The first flagged plan in display order, or `null` when none is flagged (US-02-Q-09). */
    88	export function recommendedPlanKey(plans: readonly Plan[]): string | null {
    89	  return plans.find((p) => p.isRecommended)?.key ?? null;
    90	}
