     1	import { HttpClient } from '@angular/common/http';
     2	import { Injectable, inject } from '@angular/core';
     3	import { Observable, map } from 'rxjs';
     4	import { parsePlans } from '../shared/plan';
     5	import type { Plan } from '../shared/plan.model';
     6	import { contentGet } from './content-request';
     7	
     8	const FIELDS = ['key', 'name', 'shortDescription', 'basePrice', 'sortOrder', 'isRecommended', 'isActive'];
     9	
    10	@Injectable({ providedIn: 'root' })
    11	export class PlanApi {
    12	  private readonly http = inject(HttpClient);
    13	
    14	  /** One request per country: published, active plans, only the attributes the page uses (spec 7.2). */
    15	  list(countryCode: string): Observable<Plan[]> {
    16	    const params: Record<string, string> = {
    17	      'filters[country][code][$eq]': countryCode,
    18	      'filters[isActive][$eq]': 'true',
    19	      'populate[coverages][fields][0]': 'label',
    20	      'populate[benefits][fields][0]': 'label',
    21	      'sort[0]': 'sortOrder:asc',
    22	      'sort[1]': 'key:asc',
    23	      'pagination[pageSize]': '100',
    24	    };
    25	    FIELDS.forEach((name, i) => (params[`fields[${i}]`] = name));
    26	    return contentGet(this.http, 'plans', params).pipe(map(parsePlans));
    27	  }
    28	}
=== core/plan-store.ts
     1	import { Injectable, inject } from '@angular/core';
     2	import { firstValueFrom } from 'rxjs';
     3	import type { Plan } from '../shared/plan.model';
     4	import { PlanApi } from './plan-api';
     5	
     6	/**
     7	 * Offered plans per country, kept in memory for this page load only (one plans request per page
     8	 * load, spec 7.2), shared by the plan list and the summary guard. A failed or empty answer is
     9	 * never kept, so "Reintentar" always asks again. Rejects when the request fails or times out.
    10	 */
    11	@Injectable({ providedIn: 'root' })
    12	export class PlanStore {
    13	  private readonly api = inject(PlanApi);
    14	  private readonly cache = new Map<string, Plan[]>();
    15	  private readonly inFlight = new Map<string, Promise<Plan[]>>();
    16	
    17	  load(countryCode: string): Promise<Plan[]> {
    18	    const cached = this.cache.get(countryCode);
    19	    if (cached) return Promise.resolve(cached);
    20	    const running = this.inFlight.get(countryCode);
    21	    if (running) return running;
    22	    const request = firstValueFrom(this.api.list(countryCode))
    23	      .then((plans) => {
    24	        if (plans.length > 0) this.cache.set(countryCode, plans);
    25	        return plans;
    26	      })
    27	      .finally(() => this.inFlight.delete(countryCode));
    28	    this.inFlight.set(countryCode, request);
    29	    return request;
    30	  }
    31	}
=== core/summary-step-guard.ts
     1	import { inject } from '@angular/core';
     2	import { CanActivateFn, GuardResult, RedirectCommand, Router } from '@angular/router';
     3	import { CountryStore } from './country-store';
     4	import { PlanStore } from './plan-store';
     5	import { QuoteStore } from './quote-store';
     6	import { wizardStepGuard } from './wizard-step-guard';
     7	
     8	/**
     9	 * Step 3 (`/:country/resumen`) opens only with a valid step 1 (otherwise `/<country>/datos`) and
    10	 * a chosen plan that this page load's response still offers (otherwise `/<country>/planes`).
    11	 * A failed plans request also leads to `/planes`, where the error state offers "Reintentar".
    12	 * Redirects replace the blocked address in the history (ADR-0001 note, US-02-AC-15).
    13	 */
    14	export const summaryStepGuard: CanActivateFn = async (route, state) => {
    15	  const router = inject(Router);
    16	  const countries = inject(CountryStore);
    17	  const plans = inject(PlanStore);
    18	  const quote = inject(QuoteStore);
    19	
    20	  const step1 = await (wizardStepGuard(route, state) as Promise<GuardResult>);
    21	  if (step1 !== true) return step1;
    22	
    23	  const param = (route.paramMap.get('country') ?? route.parent?.paramMap.get('country') ?? '').toLowerCase();
    24	  const toPlans = new RedirectCommand(router.parseUrl(`/${param}/planes`), { replaceUrl: true });
    25	  const chosen = quote.plan();
    26	  const country = countries.find(param);
    27	  if (!chosen || !country) return toPlans;
    28	  try {
    29	    const offered = await plans.load(country.code);
    30	    return offered.some((p) => p.key === chosen.key) ? true : toPlans;
    31	  } catch {
    32	    return toPlans;
    33	  }
    34	};
