     7	
     8	/**
     9	 * Step 3 (`/:country/resumen`) opens only with a valid step 1 (otherwise `/<country>/datos`) and
    10	 * a chosen plan that this page load's response still offers (otherwise `/<country>/planes`).
    11	 * A failed plans request also leads to `/planes`, where the error state offers "Reintentar".
    12	 * Redirects replace the blocked address in the history (ADR-0001 note, US-02-AC-15).
    13	 */
    14	export const summaryStepGuard: CanActivateFn = async (route, state) => {
    15	  const router = inject(Router);
    16	  const countries = inject(CountryStore);
    17	  const plans = inject(PlanStore);
    18	  const quote = inject(QuoteStore);
    19	
    20	  const step1 = await (wizardStepGuard(route, state) as Promise<GuardResult>);
    21	  if (step1 !== true) return step1;
    22	
    23	  const param = (route.paramMap.get('country') ?? route.parent?.paramMap.get('country') ?? '').toLowerCase();
    24	  const toPlans = new RedirectCommand(router.parseUrl(`/${param}/planes`), { replaceUrl: true });
    25	  const chosen = quote.plan();
    26	  const country = countries.find(param);
    27	  if (!chosen || !country) return toPlans;
    28	  try {
    29	    const offered = await plans.load(country.code);
    30	    return offered.some((p) => p.key === chosen.key) ? true : toPlans;
    31	  } catch {
