    59	  }
    60	
    61	  protected async load(): Promise<void> {
    62	    const country = this.country;
    63	    if (!country) {
    64	      this.status.set('error');
    65	      return;
    66	    }
    67	    this.status.set('loading');
    68	    this.showChoosePlan.set(false);
    69	    try {
