    79	      if (step1 === null) throw new Error('step 1 is not valid');
    80	      const today = this.clock();
    81	      this.items.set(
    82	        offered.map((plan) => ({
    83	          plan,
    84	          price: formatMoney(calculateFinalPrice(plan.basePrice, step1, today), country.locale, country.currencyCode),
    85	        })),
