    87	      this.status.set('ready');
    88	    } catch {
    89	      this.status.set('error');
    90	    }
    91	  }
    92	
    93	  /** The description of an option: the highlight, then the short description, then the price. */
    94	  protected describedBy(key: string): string {
    95	    const recommended = key === this.recommendedKey() ? `plan-recommended-${key} ` : '';
    96	    return `${recommended}plan-description-${key} plan-price-${key}`;
    97	  }
    98	
    99	  protected choose(key: string): void {
   100	    this.quote.choosePlan(key);
   101	    this.showChoosePlan.set(false);
   102	  }
   103	
   104	  protected back(): void {
   105	    void this.router.navigate(['/', this.countryPath(), 'datos']);
   106	  }
   107	
   108	  protected next(): void {
   109	    if (this.quote.plan() === null) {
   110	      this.showChoosePlan.set(true);
   111	      this.options()[0]?.nativeElement.focus();
   112	      return;
   113	    }
   114	    void this.router.navigate(['/', this.countryPath(), 'resumen']);
   115	  }
   116	
   117	  private countryPath(): string {
   118	    return (this.country?.code ?? this.route.snapshot.paramMap.get('country') ?? '').toLowerCase();
   119	  }
