  1	.page {
  2	  max-width: 72rem;
  3	  margin: 0 auto;
  4	  padding: 1.5rem 1rem 3rem;
  5	}
  6	h1 {
  7	  margin: 0 0 1rem;
  8	  font-size: 1.5rem;
  9	  line-height: 1.3;
 10	}
 11	h1:focus:not(:focus-visible) {
 12	  outline: none;
 13	}
 14	.plans {
 15	  display: grid;
 16	  grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr));
 17	  gap: 1rem;
 18	}
 19	.plan {
 20	  position: relative;
 21	  display: flex;
 22	  flex-direction: column;
 23	  padding: 1rem;
 24	  border: 2px solid var(--color-border);
 25	  border-radius: 0.75rem;
 26	  background: var(--color-surface);
 27	}
 28	.plan:hover {
 29	  background: var(--color-surface-hover);
 30	}
 31	.plan--recommended {
 32	  border-color: var(--color-border-strong);
 33	}
 34	.plan--chosen {
 35	  border-color: var(--color-link);
 36	  box-shadow: 0 0 0 2px var(--color-link);
 37	}
 38	.plan__header {
 39	  display: flex;
 40	  flex-wrap: wrap;
 41	  align-items: center;
 42	  gap: 0.5rem;
 43	}
 44	.plan__radio {
 45	  flex: none;
 46	  width: 1.5rem;
 47	  height: 1.5rem;
 48	  margin: 0;
 49	  /* Above the stretched label, so a pointer click on the radio itself reaches it. */
 50	  position: relative;
 51	  z-index: 1;
 52	}
 53	.plan__name {
 54	  flex: 1 1 auto;
 55	  margin: 0;
 56	  font-size: 1.125rem;
 57	}
 58	/* The label stretches over the whole card so a click anywhere chooses the plan. */
 59	.plan__name label::after {
 60	  content: '';
 61	  position: absolute;
 62	  inset: 0;
 63	  border-radius: 0.75rem;
 64	  cursor: pointer;
 65	}
 66	.plan__badge {
 67	  padding: 0.125rem 0.5rem;
 68	  border: 1px solid var(--color-border-strong);
 69	  border-radius: 999px;
 70	  font-size: 0.875rem;
 71	  font-weight: 600;
 72	}
 73	.plan__badge--chosen {
 74	  border-color: var(--color-link);
 75	  background: var(--color-link);
 76	  color: var(--color-button-text);
 77	}
 78	.plan__description {
 79	  margin: 0.75rem 0 0;
 80	  color: var(--color-muted);
