     2	import { CanActivateFn, RedirectCommand, Router } from '@angular/router';
     3	import { CountryStore } from './country-store';
     4	import { FormFieldStore } from './form-field-store';
     5	import { QuoteStore } from './quote-store';
     6	
     7	/**
     8	 * Step 2 is reachable only when the wizard state holds step 1 values for the route's country that
     9	 * pass the same validators against this page load's configuration (ADR-0001, US-01-AC-19).
    10	 * Otherwise it redirects to step 1, replacing the blocked address in the history.
    11	 */
    12	export const wizardStepGuard: CanActivateFn = async (route) => {
    13	  const router = inject(Router);
    14	  const countries = inject(CountryStore);
    15	  const fields = inject(FormFieldStore);
    16	  const quote = inject(QuoteStore);
    17	
    18	  const param = (route.paramMap.get('country') ?? route.parent?.paramMap.get('country') ?? '').toLowerCase();
    19	  const toStep1 = new RedirectCommand(router.parseUrl(`/${param}/datos`), { replaceUrl: true });
    20	
    21	  await countries.ensureLoaded();
    22	  const country = countries.find(param);
    23	  if (!country || quote.country() !== country.code) return toStep1;
    24	  try {
    25	    const configs = await fields.load(country.code);
    26	    return configs.length > 0 && quote.isStep1Valid(configs) ? true : toStep1;
    27	  } catch {
    28	    return toStep1;
    29	  }
    30	};
