  1	import { expect, type APIRequestContext, type Locator, type Page } from '@playwright/test';
  2	import { continuar, field, fillColombia, fillField } from './form';
  3	import type { AdminSession, ScopedToken } from './strapi-admin';
  4	
  5	/**
  6	 * Helpers for step 2 (the plan list) and for the US-02 write flow of the e2e tests. Everything on
  7	 * the page is found by role, name or visible text: plans are native radios (US-02-Q-13), so a plan
  8	 * is `getByRole('radio', { name: <plan name> })`. Values are fictitious (specs/US-02/seed-plans.md).
  9	 */
 10	
 11	export const HEADING = 'Elige tu plan';
 12	export const TITLE = 'Elige tu plan | Cotizador de seguro de auto';
 13	
 14	/** The browser clock of every US-02 e2e test, so that the prices are stable (spec section 11). */
 15	export const TODAY = new Date('2026-11-21T10:00:00');
 16	
 17	export const CO_PLAN_NAMES = ['Plan Básico', 'Plan Clásico', 'Plan Total'];
 18	export const CL_PLAN_NAMES = ['Plan Esencial', 'Plan Protegido', 'Plan Premium'];
 19	/** Final prices of the seed with the step 1 values below at 2026-11-21 (US-02-AC-07). */
 20	export const CO_PRICES = ['$935.000', '$1.540.000', '$2.310.000'];
 21	export const CL_PRICES = ['$319.000', '$528.000', '$792.000'];
 22	/** Seeded plans that are never offered: draft only or inactive (US-02-AC-01, AC-08). */
 23	export const CO_HIDDEN_NAMES = ['Plan Joven', 'Plan Total Plus'];
 24	export const CL_HIDDEN_NAMES = ['Plan Flex', 'Plan Premium Plus'];
 25	
 26	export const CL_CONSENT = 'Acepto el tratamiento de mis datos personales.';
 27	
 28	/** "I completed step 1 in Chile" of US-02 spec section 5. */
 29	export const CL_VALID: Record<string, string | boolean> = {
 30	  RUT: '12.345.678-5',
 31	  'Nombre completo': 'Ana Prueba Ficticia',
 32	  'Fecha de nacimiento': '1990-05-15',
 33	  Ciudad: 'Santiago',
 34	  Patente: 'BCDF12',
 35	  Marca: 'Kia',
 36	  Modelo: 'Rio 5',
 37	  Año: '2022',
 38	  [CL_CONSENT]: true,
 39	};
 40	
 41	export async function fillChile(page: Page, overrides: Record<string, string | boolean | null> = {}): Promise<void> {
 42	  const values: Record<string, string | boolean | null> = { ...CL_VALID, ...overrides };
 43	  for (const [label, value] of Object.entries(values)) {
 44	    if (value === null) continue;
 45	    await fillField(page, label, value);
 46	  }
 47	}
 48	
 49	/** A price as the page may write it: whitespace between the symbol and the digits is allowed (BR-03). */
 50	export function pricePattern(price: string): RegExp {
 51	  const digits = price.replace(/[^\d.]/g, '').replace(/\./g, '\\.');
 52	  return new RegExp(`\\$\\s*${digits}(?![\\d.])`);
 53	}
 54	
 55	export function plan(page: Page, name: string): Locator {
 56	  return page.getByRole('radio', { name, exact: true });
 57	}
 58	
 59	export function plans(page: Page): Locator {
 60	  return page.getByRole('radio');
 61	}
 62	
 63	export function atras(page: Page): Locator {
 64	  return page.getByRole('button', { name: 'Atrás' });
 65	}
 66	
 67	/** The plan names shown, in order (each option's accessible name is its plan name, US-02-AC-17). */
 68	export async function expectPlanNames(page: Page, names: string[]): Promise<void> {
 69	  await expect(plans(page)).toHaveCount(names.length);
 70	  for (const [index, name] of names.entries()) {
 71	    await expect(plans(page).nth(index)).toHaveAccessibleName(name);
 72	  }
 73	}
 74	
 75	/** The final price of each plan is part of its accessible description (US-02-AC-17). */
 76	export async function expectPrices(page: Page, names: string[], prices: string[]): Promise<void> {
 77	  for (const [index, name] of names.entries()) {
 78	    await expect(plan(page, name)).toHaveAccessibleDescription(pricePattern(prices[index]));
 79	  }
 80	}
 81	
 82	/** Every control of step 1 shows the value that was entered (US-01-AC-04, AC-20, AC-21); no error is shown. */
 83	export async function expectEntered(page: Page, values: Record<string, string | boolean>): Promise<void> {
 84	  for (const [label, value] of Object.entries(values)) {
 85	    const control = field(page, label);
 86	    const tag = await control.evaluate((el) => el.tagName.toLowerCase());
 87	    const type = await control.evaluate((el) => (el as HTMLInputElement).type);
 88	    if (tag === 'select') {
 89	      await expect.poll(() => control.evaluate((el) => (el as HTMLSelectElement).selectedOptions[0]?.textContent?.trim()), { message: label }).toBe(value);
 90	    } else if (type === 'checkbox') {
 91	      await (value ? expect(control).toBeChecked() : expect(control).not.toBeChecked());
 92	    } else {
 93	      await expect(control, label).toHaveValue(value as string);
 94	    }
 95	    await expect(control).not.toHaveAttribute('aria-invalid', 'true');
 96	  }
 97	}
 98	
 99	/** Complete step 1 for Colombia (US-01-AC-04 values) and activate "Continuar". */
100	export async function reachPlansInColombia(page: Page): Promise<void> {
101	  await page.clock.setFixedTime(TODAY);
102	  await page.goto('/co/datos');
103	  await expect(field(page, 'Placa')).toBeVisible();
104	  await fillColombia(page);
105	  await continuar(page).click();
106	  await expect(page).toHaveURL(/\/co\/planes$/);
107	  await expect(page.getByRole('heading', { level: 1, name: HEADING })).toBeVisible();
108	}
109	
110	export async function reachPlansInChile(page: Page): Promise<void> {
111	  await page.clock.setFixedTime(TODAY);
112	  await page.goto('/cl/datos');
113	  await expect(field(page, 'Patente')).toBeVisible();
114	  await fillChile(page);
115	  await continuar(page).click();
116	  await expect(page).toHaveURL(/\/cl\/planes$/);
117	  await expect(page.getByRole('heading', { level: 1, name: HEADING })).toBeVisible();
118	}
119	
120	// ---------------------------------------------------------------------------------------------
121	// Write flow for US-02-AC-12 (ADR-0005 general rule, spec 7.5): Node process only
122	// ---------------------------------------------------------------------------------------------
123	
124	const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
125	/** Exactly these three permissions (spec 7.5): create and delete of `plan`, and `country.find` for the relation. */
126	export const PLAN_TOKEN_SCOPE = ['api::plan.plan.create', 'api::plan.plan.delete', 'api::country.country.find'];
127	
128	async function expectOk(response: { ok(): boolean; status(): number }, what: string): Promise<void> {
129	  // Status and a fixed description only: response bodies may carry tokens.
130	  if (!response.ok()) throw new Error(`${what} failed with HTTP ${response.status()}`);
131	}
132	
133	export async function createPlanToken(api: APIRequestContext, session: AdminSession, name: string): Promise<ScopedToken> {
134	  const response = await api.post('/admin/api-tokens', {
135	    headers: { Authorization: `Bearer ${session.jwt}` },
136	    data: {
137	      name,
138	      description: 'Temporary token of the US-02-AC-12 end-to-end test; deleted in teardown.',
139	      type: 'custom',
140	      lifespan: SEVEN_DAYS_MS,
141	      permissions: PLAN_TOKEN_SCOPE,
142	    },
143	  });
144	  await expectOk(response, 'Creating the scoped API token');
145	  const body = (await response.json()) as { data?: { id?: number; accessKey?: string } };
146	  if (body.data?.id === undefined || !body.data.accessKey) throw new Error('Strapi returned no API token');
147	  return { id: body.data.id, accessKey: body.data.accessKey };
148	}
149	
150	export interface NewPlan {
151	  key: string;
152	  name: string;
153	  shortDescription: string;
154	  basePrice: number;
155	  sortOrder: number;
156	  isActive: boolean;
157	  isRecommended: boolean;
158	  coverages: string[];
159	}
160	
161	/** A REST POST publishes immediately unless `status=draft` is passed (ADR-0002, Strapi REST docs). */
162	export async function createPlan(api: APIRequestContext, token: ScopedToken, countryDocumentId: string, plan: NewPlan): Promise<string> {
163	  const { coverages, ...attributes } = plan;
164	  const response = await api.post('/api/plans', {
165	    headers: { Authorization: `Bearer ${token.accessKey}` },
166	    data: { data: { ...attributes, coverages: coverages.map((label) => ({ label })), country: { connect: [countryDocumentId] } } },
167	  });
168	  await expectOk(response, 'Creating the plan');
169	  const body = (await response.json()) as { data?: { documentId?: string } };
170	  if (!body.data?.documentId) throw new Error('Strapi returned no documentId for the new plan');
171	  return body.data.documentId;
172	}
173	
174	export async function deletePlan(api: APIRequestContext, token: ScopedToken, documentId: string): Promise<void> {
175	  const response = await api.delete(`/api/plans/${documentId}`, { headers: { Authorization: `Bearer ${token.accessKey}` } });
176	  await expectOk(response, 'Deleting the plan');
177	}
178	
179	/** Pre-test cleanup: deletes published plans left with the test's key by a crashed run (read is public). */
180	export async function deleteStalePlans(api: APIRequestContext, token: ScopedToken, key: string): Promise<void> {
181	  const response = await api.get('/api/plans', { params: { 'filters[key][$eq]': key, 'pagination[pageSize]': '100' } });
182	  await expectOk(response, 'Reading leftover plans');
183	  const body = (await response.json()) as { data?: { documentId?: string }[] };
184	  for (const stale of body.data ?? []) {
185	    if (stale.documentId) await deletePlan(api, token, stale.documentId);
186	  }
187	}

